mapper.select:
SELECT user_id AS userId, item_id AS itemId, create_time AS actionTime, NULL AS rating
FROM like_record
WHERE item_type = #{itemType}
AND create_time >= #{since}

SELECT user_id AS userId, item_id AS itemId, create_time AS actionTime, NULL AS rating
FROM collection
WHERE item_type = #{itemType}
AND create_time >= #{since}

SELECT user_id AS userId, item_id AS itemId, create_time AS actionTime, rating AS rating
FROM comment
WHERE item_type = #{itemType}
  AND status = 1
AND create_time >= #{since}

SELECT user_id AS userId, item_id AS itemId, create_time AS actionTime, NULL AS rating
FROM cart
WHERE item_type = #{itemType}
AND create_time >= #{since}

SELECT user_id AS userId, item_id AS itemId, create_time AS actionTime, NULL AS rating
FROM orders
WHERE item_type = #{itemType}
  AND status IN ('1', '3')
AND create_time >= #{since}

SELECT user_id AS userId, item_id AS itemId, create_time AS actionTime,
       NULL AS rating, 'LIKE' AS actionType
FROM like_record
WHERE item_type = #{itemType} AND user_id = #{userId}
  AND create_time >= #{since}
UNION ALL
SELECT user_id, item_id, create_time, NULL, 'COLLECT'
FROM collection
WHERE item_type = #{itemType} AND user_id = #{userId}
  AND create_time >= #{since}
UNION ALL
SELECT user_id, item_id, create_time, rating, 'COMMENT'
FROM comment
WHERE item_type = #{itemType} AND user_id = #{userId} AND status = 1
  AND create_time >= #{since}
UNION ALL
SELECT user_id, item_id, create_time, NULL, 'CART'
FROM cart
WHERE item_type = #{itemType} AND user_id = #{userId}
  AND create_time >= #{since}
UNION ALL
SELECT user_id, item_id, create_time, NULL, 'ORDER'
FROM orders
WHERE item_type = #{itemType} AND user_id = #{userId} AND status IN ('1', '3')
  AND create_time >= #{since}
